        $result[$m] = $m;
        $idx = array_search($m, $unused);
        array_splice($unused, $idx, 1);
        continue;
    } else {
        $k = bcsub($k, $count1);
        $count2 = ($size - 2 >= 0) ? $f[$size - 2] : "0";

        $others = [];
        foreach ($unused as $x) {
            if ($x != $m) $others[] = $x;
        }
        sort($others);

        foreach ($others as $v) {
            if (bccomp($k, $count2) <= 0) {
                $result[$m] = $v;
                $result[$v] = $m;
                $newUnused = [];
