$MOD = 1000000007;

function modpow($base, $exp, $mod) {
    $base = $base % $mod;
    if ($base < 0) $base += $mod;
    $result = 1;
    while ($exp > 0) {
        if ($exp & 1) {
            $result = ($result * $base) % $mod;
        }
        $exp >>= 1;
        if ($exp > 0) {
            $base = ($base * $base) % $mod;
        }
    }
    return $result;
}

// factorize x
$primes = [];
$temp = $x;
for ($d = 2; $d * $d <= $temp; $d++) {
    if ($temp % $d == 0) {
        $primes[] = $d;
        while ($temp % $d == 0) {
            $temp = intdiv($temp, $d);
        }
    }
}
if ($temp > 1) {
    $primes[] = $temp;
}

$answer = 1;

foreach ($primes as $p) {
    // compute exponent e = sum floor(n / p^k) for k=1,2,...
    $e = 0;
    $pk = $p;
    while ($pk <= $n) {
        $e += intdiv($n, $pk);
        // check for overflow before multiplying
        if ($pk > intdiv($n, $p)) {
            break;
        }
        $pk *= $p;
    }
    $answer = ($answer * modpow($p, $e, $MOD)) % $MOD;
