fscanf(STDIN, "%d %d %d %d", $a, $b, $c, $l);

function countBad($big, $s1, $s2, $l) {
    // count (x,y,z) with x+y+z<=l, x,y,z>=0, such that
    // (big + x) >= (s1 + y) + (s2 + z)
    $e = $s1 + $s2 - $big;
