function factorize($n) {
    $factors = [];
    while ($n % 2 == 0) {
        $factors[2] = ($factors[2] ?? 0) + 1;
        $n = intdiv($n, 2);
    }
    for ($p = 3; $p * $p <= $n; $p += 2) {
        while ($n % $p == 0) {
            $factors[$p] = ($factors[$p] ?? 0) + 1;
            $n = intdiv($n, $p);
        }
